-- Devis Studio CRM — migration 001_init
--
-- Target: MySQL 8, InnoDB, utf8mb4. Import ONCE into an EMPTY database via phpMyAdmin.
-- Mirrors the current client model: src/lib/validation/schemas.ts (Zod) and
-- src/lib/db/database.ts (Dexie stores and indexes).
-- Contains no data and no credentials.
--
-- Conventions:
--   * id columns: UUID strings generated by the application (CHAR(36), ascii_bin);
--   * money: whole kopecks in BIGINT, never FLOAT/DOUBLE;
--   * timestamps and dates: the application stores ISO-8601 UTC strings
--     (Date#toISOString); the API will store them as DATETIME(3) in UTC;
--   * optional text: NULL when absent (Zod turns empty strings into undefined);
--   * long free text: MEDIUMTEXT. Zod allows 20 000 code points; at up to 4 bytes
--     each (emoji) that is 80 000 bytes, more than TEXT holds (65 535 bytes);
--   * order_items.quantity: DOUBLE, the same IEEE-754 number the client uses
--     for quantity × price; line totals are rounded to whole kopecks by the app.
--
-- Users / sessions for owner authentication are intentionally NOT created here:
-- they belong to a separate migration of the authentication stage.

SET NAMES utf8mb4;

-- Created first and without IF NOT EXISTS: importing this file into a database that
-- already contains the schema fails here, before any other table is touched.
CREATE TABLE `schema_migrations` (
  `version` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `applied_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- clientSchema
CREATE TABLE `clients` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `contact_name` VARCHAR(255) NULL,
  `phone` VARCHAR(255) NULL,
  `email` VARCHAR(255) NULL,
  `telegram` VARCHAR(255) NULL,
  `max_contact` VARCHAR(255) NULL,
  `other_contact` MEDIUMTEXT NULL,
  `source` VARCHAR(255) NULL,
  `notes` MEDIUMTEXT NULL,
  `tags` JSON NULL,
  `is_archived` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME(3) NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_clients_name` (`name`),
  KEY `idx_clients_archived_name` (`is_archived`, `name`),
  CONSTRAINT `chk_clients_name_not_blank` CHECK (CHAR_LENGTH(TRIM(`name`)) > 0),
  CONSTRAINT `chk_clients_is_archived` CHECK (`is_archived` IN (0, 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- orderSchema
CREATE TABLE `orders` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `number` INT UNSIGNED NOT NULL,
  `client_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `description` MEDIUMTEXT NULL,
  `status` ENUM('new', 'in_progress', 'waiting', 'completed', 'cancelled') NOT NULL DEFAULT 'new',
  `order_date` DATETIME(3) NOT NULL,
  `due_date` DATETIME(3) NULL,
  `completed_at` DATETIME(3) NULL,
  `discount_minor` BIGINT NOT NULL DEFAULT 0,
  `total_minor` BIGINT NOT NULL DEFAULT 0,
  `paid_minor` BIGINT NOT NULL DEFAULT 0,
  `notes` MEDIUMTEXT NULL,
  `is_archived` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME(3) NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orders_number` (`number`),
  KEY `idx_orders_client_order_date` (`client_id`, `order_date`),
  KEY `idx_orders_order_date` (`order_date`),
  KEY `idx_orders_due_date` (`due_date`),
  KEY `idx_orders_status` (`status`),
  KEY `idx_orders_archived` (`is_archived`),
  -- Clients with orders are archived, never deleted (deleteClientIfNoOrders).
  CONSTRAINT `fk_orders_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`)
    ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_orders_number_positive` CHECK (`number` > 0),
  CONSTRAINT `chk_orders_title_not_blank` CHECK (CHAR_LENGTH(TRIM(`title`)) > 0),
  CONSTRAINT `chk_orders_discount_non_negative` CHECK (`discount_minor` >= 0),
  CONSTRAINT `chk_orders_total_non_negative` CHECK (`total_minor` >= 0),
  -- assertPaidNotExceedsTotal: payments may never exceed the order total.
  CONSTRAINT `chk_orders_paid_range` CHECK (`paid_minor` >= 0 AND `paid_minor` <= `total_minor`),
  CONSTRAINT `chk_orders_is_archived` CHECK (`is_archived` IN (0, 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- orderItemSchema
CREATE TABLE `order_items` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `order_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `description` MEDIUMTEXT NULL,
  `quantity` DOUBLE NOT NULL,
  `unit` VARCHAR(64) NOT NULL,
  `unit_price_minor` BIGINT NOT NULL,
  `line_total_minor` BIGINT NOT NULL,
  `sort_order` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_order_items_order_sort` (`order_id`, `sort_order`),
  -- Items belong to their order and are rewritten together with it (updateOrder).
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
    ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_order_items_name_not_blank` CHECK (CHAR_LENGTH(TRIM(`name`)) > 0),
  CONSTRAINT `chk_order_items_unit_not_blank` CHECK (CHAR_LENGTH(TRIM(`unit`)) > 0),
  CONSTRAINT `chk_order_items_quantity_positive` CHECK (`quantity` > 0),
  CONSTRAINT `chk_order_items_unit_price_non_negative` CHECK (`unit_price_minor` >= 0),
  CONSTRAINT `chk_order_items_line_total_non_negative` CHECK (`line_total_minor` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- paymentSchema
CREATE TABLE `payments` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `order_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `amount_minor` BIGINT NOT NULL,
  `payment_date` DATETIME(3) NOT NULL,
  `method` ENUM('cash', 'bank_transfer', 'other') NOT NULL,
  `comment` MEDIUMTEXT NULL,
  `created_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payments_order_payment_date` (`order_id`, `payment_date`),
  KEY `idx_payments_payment_date` (`payment_date`),
  -- Financial history is never removed implicitly together with an order.
  CONSTRAINT `fk_payments_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
    ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_payments_amount_positive` CHECK (`amount_minor` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dexie appMeta: key/value (e.g. nextOrderNumber). A missing nextOrderNumber means 1,
-- exactly as in src/lib/repositories/orders.ts, so no seed row is inserted.
CREATE TABLE `app_meta` (
  `meta_key` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `meta_value` JSON NOT NULL,
  PRIMARY KEY (`meta_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `schema_migrations` (`version`) VALUES ('001_init');
